<?php
declare(strict_types=1);
final class Schema19LifecycleProvenanceTest extends WP_UnitTestCase{
 protected function setUp():void{parent::setUp();DigiForge\Core\Activator::activate();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));}
 public function testSchema19CreatesProvenanceAndExplicitClosureState():void{global $wpdb;self::assertSame(19,(int)get_option('digiforge_db_schema_version'));self::assertSame(DigiForge\Database\Tables::pod_authorization_bindings(),$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',DigiForge\Database\Tables::pod_authorization_bindings())));$columns=$wpdb->get_col('DESC '.DigiForge\Database\Tables::pod_lifecycle_closures(),0);self::assertContains('external_execution_state',$columns);}
 public function testHistoryUsesProspectiveBindingBeforeClosure():void{global $wpdb;$now=current_time('mysql',true);$auth=hash('sha256','v19-history-auth');$nonce='v19_history_nonce_123456789012345';$nh=hash('sha256',$nonce);$ph=hash('sha256','v19-history-package');$wpdb->insert(DigiForge\Database\Tables::pod_authorization_packages(),['order_id'=>1,'render_evidence_id'=>1,'provider_mapping_id'=>1,'ownership_mapping_id'=>1,'readiness_hash'=>hash('sha256','v19-ready'),'package_hash'=>$ph,'state'=>'APPROVED_PACKAGE','approved_by'=>get_current_user_id(),'approved_at'=>$now,'external_execution_authorized'=>0,'external_execution_performed'=>0,'created_at'=>$now]);$pid=(int)$wpdb->insert_id;self::assertTrue(DigiForge\POD\ExecutionNonceLedger::consume($nonce,$auth,get_current_user_id()));$wpdb->insert(DigiForge\Database\Tables::pod_authorization_bindings(),['package_id'=>$pid,'package_hash'=>$ph,'authorization_hash'=>$auth,'nonce_hash'=>$nh,'bound_by'=>get_current_user_id(),'bound_at'=>$now]);$h=(new DigiForge\POD\ProductionLifecycleHistoryReadModel())->project($auth);self::assertSame('CONSUMED_AWAITING_OUTCOME',$h['lifecycle_state']);self::assertSame($pid,(int)$h['authorization_package']['id']);self::assertSame($auth,$h['authorization_binding']['authorization_hash']);self::assertSame('BOUND',$h['provenance_state']);}
 public function testClosureRejectsConflictingProspectiveProvenance():void{global $wpdb;$now=current_time('mysql',true);$auth=hash('sha256','v19-conflict-auth');$nonce='v19_conflict_nonce_12345678901234';$nh=hash('sha256',$nonce);$ph=hash('sha256','v19-package-a');$wpdb->insert(DigiForge\Database\Tables::pod_authorization_packages(),['order_id'=>1,'render_evidence_id'=>1,'provider_mapping_id'=>1,'ownership_mapping_id'=>1,'readiness_hash'=>hash('sha256','v19-r'),'package_hash'=>$ph,'state'=>'APPROVED_PACKAGE','approved_by'=>get_current_user_id(),'approved_at'=>$now,'external_execution_authorized'=>0,'external_execution_performed'=>0,'created_at'=>$now]);$pid=(int)$wpdb->insert_id;self::assertTrue(DigiForge\POD\ExecutionNonceLedger::consume($nonce,$auth,get_current_user_id()));$wpdb->insert(DigiForge\Database\Tables::pod_authorization_bindings(),['package_id'=>$pid+999,'package_hash'=>hash('sha256','wrong'),'authorization_hash'=>$auth,'nonce_hash'=>$nh,'bound_by'=>get_current_user_id(),'bound_at'=>$now]);$fh=hash('sha256','v19-f');$wpdb->insert(DigiForge\Database\Tables::pod_execution_failures(),['action'=>'X','evidence_hash'=>hash('sha256','v19-e'),'authorization_hash'=>$auth,'nonce_hash'=>$nh,'failure_category'=>'adapter_error','failure_code'=>'timeout','executed_by'=>get_current_user_id(),'recorded_at'=>$now,'failure_hash'=>$fh,'created_at'=>$now]);$projection=(new DigiForge\POD\ConsumedPermitOutcomeReadModel())->project($auth);$closure=(new DigiForge\POD\ProductionLifecycleClosure())->close(['id'=>$pid,'package_hash'=>$ph,'state'=>'APPROVED_PACKAGE','approved_by'=>get_current_user_id()],$projection,get_current_user_id());$saved=DigiForge\POD\ProductionLifecycleClosureRepository::save($closure);self::assertWPError($saved);self::assertSame('production_closure_provenance_conflict',$saved->get_error_code());}
 public function testAtomicConsumptionPersistsNonceAndBindingTogether():void{global $wpdb;$auth=hash('sha256','atomic-auth');$nonce='atomic_nonce_12345678901234567890';$ph=hash('sha256','atomic-package');$saved=DigiForge\POD\ProductionExecutionConsumptionRepository::consume($nonce,$auth,77,$ph,get_current_user_id());self::assertFalse(is_wp_error($saved));self::assertSame($auth,$wpdb->get_var($wpdb->prepare('SELECT authorization_hash FROM '.DigiForge\Database\Tables::pod_execution_nonces().' WHERE nonce_hash=%s',hash('sha256',$nonce))));$binding=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DigiForge\Database\Tables::pod_authorization_bindings().' WHERE authorization_hash=%s',$auth),ARRAY_A);self::assertSame(77,(int)$binding['package_id']);self::assertSame($ph,$binding['package_hash']);$replay=DigiForge\POD\ProductionExecutionConsumptionRepository::consume($nonce,$auth,77,$ph,get_current_user_id());self::assertWPError($replay);self::assertSame('digiforge_execution_replay',$replay->get_error_code());}
 public function testBindingFailureRollsBackNonceConsumption():void{global $wpdb;$auth=hash('sha256','rollback-auth');$nonce='rollback_nonce_123456789012345678';$ph=hash('sha256','rollback-package');$wpdb->insert(DigiForge\Database\Tables::pod_authorization_bindings(),['package_id'=>1,'package_hash'=>hash('sha256','existing'),'authorization_hash'=>$auth,'nonce_hash'=>hash('sha256','other_nonce_12345678901234567890'),'bound_by'=>get_current_user_id(),'bound_at'=>current_time('mysql',true)]);$saved=DigiForge\POD\ProductionExecutionConsumptionRepository::consume($nonce,$auth,2,$ph,get_current_user_id());self::assertWPError($saved);self::assertSame('production_permit_package_binding_conflict',$saved->get_error_code());self::assertNull($wpdb->get_var($wpdb->prepare('SELECT authorization_hash FROM '.DigiForge\Database\Tables::pod_execution_nonces().' WHERE nonce_hash=%s',hash('sha256',$nonce))));}
 public function testHistoryRejectsBindingPackageHashMismatch():void{global $wpdb;$now=current_time('mysql',true);$auth=hash('sha256','history-hash-conflict');$ph=hash('sha256','actual-package');$wpdb->insert(DigiForge\Database\Tables::pod_authorization_packages(),['order_id'=>1,'render_evidence_id'=>1,'provider_mapping_id'=>1,'ownership_mapping_id'=>1,'readiness_hash'=>hash('sha256','r'),'package_hash'=>$ph,'state'=>'APPROVED_PACKAGE','approved_by'=>get_current_user_id(),'approved_at'=>$now,'external_execution_authorized'=>0,'external_execution_performed'=>0,'created_at'=>$now]);$pid=(int)$wpdb->insert_id;$wpdb->insert(DigiForge\Database\Tables::pod_authorization_bindings(),['package_id'=>$pid,'package_hash'=>hash('sha256','wrong-package'),'authorization_hash'=>$auth,'nonce_hash'=>hash('sha256','history_nonce_123456789012345678'),'bound_by'=>get_current_user_id(),'bound_at'=>$now]);$h=(new DigiForge\POD\ProductionLifecycleHistoryReadModel())->project($auth);self::assertWPError($h);self::assertSame('production_history_provenance_conflict',$h->get_error_code());}

}
